    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    def word(m):
        return ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(rng.randint(1, m)))
    tests = [
        fmt(['getmax']),
        fmt(['getmin', 'inc a', 'getmax', 'getmin', 'dec a', 'getmax']),
        fmt(['inc a', 'inc b', 'inc c', 'getmax', 'getmin', 'dec a', 'getmax', 'getmin']),
        fmt(['inc z', 'inc z', 'inc y', 'inc y', 'inc y', 'dec y', 'getmax', 'getmin', 'dec z', 'getmin', 'getmax']),
    ]
    def small(n, keys, qp):
        ops, cnt = [], {}
        for _ in range(n):
            r = rng.random()
            if r < qp:
                ops.append(rng.choice(['getmax', 'getmin']))
            elif cnt and r < qp + (1 - qp) * 0.4:
                k = rng.choice(sorted(cnt))
                ops.append('dec ' + k)
                cnt[k] -= 1
                if cnt[k] == 0:
                    del cnt[k]
            else:
                k = rng.choice(keys)
                ops.append('inc ' + k)
                cnt[k] = cnt.get(k, 0) + 1
