            ops.append('dec ' + k)
            cnt[k] -= 1
            if cnt[k] == 0:
                del cnt[k]
                live[i] = live[-1]
                live.pop()
        else:
            k = rng.choice(keys)
            ops.append('inc ' + k)
            if k not in cnt:
